const _TP_IDX = { en: 1, es: 2, de: 3, fr: 4 };
const _TP_PRE = TP_DYN.map(w => {
    const parts = w[0].split(/\{\d+\}/);
    const nazwy = [...w[0].matchAll(/\{(\d+)\}/g)].map(x => x[1]);
    const re = new RegExp('^' + parts.map(p => p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('([\\s\\S]*?)') + '$');
    return { w, re, nazwy };
});
// Tłumaczy polski komunikat (także z już wstawionymi wartościami) na aktualny język.
function tpAuto(tekst) {
    let kod = window.aktualnyJezyk;
    if (!kod) { try { kod = localStorage.getItem('jezyk_priceai'); } catch (e) {} }
    kod = kod || 'pl';
    const idx = _TP_IDX[kod];
    if (!idx || typeof tekst !== 'string') return tekst;
    const s = tekst.trim();
    for (const p of _TP_PRE) {
        const m = s.match(p.re);
        if (!m) continue;
        let wynik = p.w[idx];
        p.nazwy.forEach((n, i) => { wynik = wynik.split('{' + n + '}').join(m[i + 1]); });
        return wynik;
    }
    return tekst;
}

// Regulamin i Polityka Prywatności: wersja polska dla PL, angielska dla pozostałych języków
// (do czasu przygotowania wersji ES/DE/FR).
const LINKI_PRAWNE_EN = { 'regulamin.html': 'terms-en.html', 'polityka-prywatnosci.html': 'privacy-en.html' };
function przelaczLinkiPrawne(kod) {
    document.querySelectorAll('a[href]').forEach(a => {
        const orig = a.getAttribute('data-pl-href') || a.getAttribute('href');
        if (!LINKI_PRAWNE_EN[orig]) return;
        a.setAttribute('data-pl-href', orig);
        a.setAttribute('href', kod === 'pl' ? orig : LINKI_PRAWNE_EN[orig]);
    });
}
